function AdminUsers({ users, setUsers }) {
  const emptyForm = { name: "", username: "", password: "", role: "teacher", area: "", contact: "", qualification: "" };
  const [form, setForm] = useState(emptyForm);
  const [editId, setEditId] = useState(null);
  const [err, setErr] = useState("");

  const resetForm = () => {
    setForm(emptyForm);
    setEditId(null);
    setErr("");
  };

  const submit = () => {
    if (!form.name.trim() || !form.username.trim() || !form.password.trim()) {
      setErr("Sab fields bharen.");
      return;
    }
    if (form.role === "counsellor" && (!form.area || !form.contact.trim() || !form.qualification)) {
      setErr("Location, Contact aur Qualification bharen.");
      return;
    }
    const dupe = users.find(
      (u) => u.username.toLowerCase() === form.username.trim().toLowerCase() && u.id !== editId
    );
    if (dupe) {
      setErr("Yeh username pehle se hai.");
      return;
    }
    if (editId) {
      setUsers(users.map((u) => (u.id === editId ? { ...u, ...form } : u)));
    } else {
      setUsers([...users, { id: nextId("u"), ...form }]);
    }
    resetForm();
  };

  const edit = (u) => {
    setEditId(u.id);
    setForm({
      name: u.name, username: u.username, password: u.password, role: u.role,
      area: u.area || "", contact: u.contact || "", qualification: u.qualification || "",
    });
    setErr("");
  };

  const remove = (id) => {
    if (users.find((u) => u.id === id)?.username === "admin") return;
    setUsers(users.filter((u) => u.id !== id));
    if (editId === id) resetForm();
  };

  return (
    <div className="grid md:grid-cols-[1fr_320px] gap-5">
      <Paper className="p-5">
        <div className="flex items-center gap-2 mb-4 text-[#1B2A4A]">
          <Users size={17} />
          <h2 className="font-serif text-[18px]">Sab Users</h2>
        </div>
        <div className="divide-y divide-[#E4DDC9]">
          {users.map((u) => (
            <div key={u.id} className="flex items-center justify-between py-2.5">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-full bg-[#1B2A4A]/10 flex items-center justify-center text-[#1B2A4A]">
                  <RoleIcon role={u.role} size={15} />
                </div>
                <div>
                  <div className="text-[14px] font-semibold text-[#2B2A26]">{u.name}</div>
                  <div className="text-[12px] text-[#8A8371]">
                    @{u.username}{u.role === "counsellor" && u.area ? ` · ${u.area}` : ""}
                  </div>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Badge
                  text={u.role}
                  color={u.role === "admin" ? "#B54B3D" : u.role === "teacher" ? "#1F6F43" : "#C98A2E"}
                />
                <button onClick={() => edit(u)} className="p-1.5 text-[#6B6353] hover:text-[#1B2A4A]">
                  <Pencil size={14} />
                </button>
                {u.username !== "admin" && (
                  <button onClick={() => remove(u.id)} className="p-1.5 text-[#6B6353] hover:text-[#B54B3D]">
                    <Trash2 size={14} />
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </Paper>

      <Paper className="p-5 h-fit">
        <div className="flex items-center gap-2 mb-4 text-[#1B2A4A]">
          <UserPlus size={17} />
          <h2 className="font-serif text-[18px]">{editId ? "User Edit Karein" : "Naya User"}</h2>
        </div>
        <div>
          <Field label="Naam">
            <input className={inputCls} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
          </Field>
          <Field label="Username">
            <input className={inputCls} value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} />
          </Field>
          <Field label="Password">
            <input className={inputCls} value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
          </Field>
          <Field label="Role">
            <select className={inputCls} value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
              <option value="teacher">Teacher</option>
              <option value="counsellor">Counsellor</option>
              <option value="admin">Admin</option>
            </select>
          </Field>
          {form.role === "counsellor" && (
            <>
              <Field label="Location / Area">
                <select className={inputCls} value={form.area} onChange={(e) => setForm({ ...form, area: e.target.value })}>
                  <option value="">Select Area</option>
                  {AREA_LIST.map((a) => <option key={a} value={a}>{a}</option>)}
                </select>
              </Field>
              <Field label="Contact Number">
                <input className={inputCls} value={form.contact} onChange={(e) => setForm({ ...form, contact: e.target.value })} />
              </Field>
              <Field label="Qualification">
                <select className={inputCls} value={form.qualification} onChange={(e) => setForm({ ...form, qualification: e.target.value })}>
                  <option value="">Select Qualification</option>
                  {QUALIFICATION_LEVELS.map((q) => <option key={q} value={q}>{q}</option>)}
                </select>
              </Field>
            </>
          )}
          {err && <div className="text-[#B54B3D] text-[12px] mb-3 font-medium">{err}</div>}
          <div className="flex gap-2 mt-1">
            <Btn onClick={submit}>{editId ? <><Check size={14}/> Save</> : <><Plus size={14}/> Add User</>}</Btn>
            {editId && <Btn variant="ghost" onClick={resetForm}><X size={14}/> Cancel</Btn>}
          </div>
        </div>
      </Paper>
    </div>
  );
}

