function VolunteerFlow({ leads, setLeads, teacherLeads, setTeacherLeads, onLogout }) {
  const [step, setStep] = useState("info"); // info | choose | student | teacher | done
  const [vol, setVol] = useState({ name: "", mobile: "" });
  const [volErr, setVolErr] = useState("");

  const startInfo = () => {
    if (!vol.name.trim() || !vol.mobile.trim()) {
      setVolErr("Naam aur Mobile Number zaroori hai.");
      return;
    }
    setVolErr("");
    setStep("choose");
  };

  const createdByTag = `Volunteer: ${vol.name} (${vol.mobile})`;

  return (
    <div className="mt-root min-h-screen bg-[#F3EFE4]">
      <FontStyles />
      <div className="bg-[#1B2A4A] text-[#FAF7EF]">
        <div className="max-w-md mx-auto px-5 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full border-2 border-[#C98A2E] text-[#C98A2E] flex items-center justify-center shrink-0">
              <UserPlus size={14} />
            </div>
            <div className="font-serif font-semibold text-[17px] leading-tight">My Teachers</div>
          </div>
          <button onClick={onLogout} className="p-2 rounded-[3px] hover:bg-white/10 text-[#FAF7EF]/80" title="Logout">
            <LogOut size={17} />
          </button>
        </div>
      </div>

      <div className="max-w-md mx-auto px-5 py-6">
        {step === "info" && (
          <Paper className="p-5 mt-fadein">
            <div className="flex items-center gap-2 mb-4 text-[#1B2A4A]">
              <UserIcon size={17} />
              <h2 className="font-serif text-[18px]">Apni Detail Bharen</h2>
            </div>
            <div>
              <Field label="Aapka Naam">
                <input className={inputCls} value={vol.name} onChange={(e) => setVol({ ...vol, name: e.target.value })} autoFocus />
              </Field>
              <Field label="Mobile Number">
                <input className={inputCls} value={vol.mobile} onChange={(e) => setVol({ ...vol, mobile: e.target.value })} />
              </Field>
              {volErr && <div className="text-[#B54B3D] text-[12px] mb-3 font-medium">{volErr}</div>}
              <Btn onClick={startInfo} className="w-full justify-center">Continue <ChevronRight size={15} /></Btn>
            </div>
          </Paper>
        )}

        {step === "choose" && (
          <div className="mt-fadein space-y-3">
            <div className="text-[13px] text-[#6B6353] mb-2">Namaste <b>{vol.name}</b>! Kis type ka lead add karna hai?</div>
            <button
              onClick={() => setStep("student")}
              className="w-full flex items-center gap-3 p-4 rounded-[3px] bg-white border border-[#D9D2C1] hover:border-[#1B2A4A] transition-colors text-left"
            >
              <div className="w-10 h-10 rounded-full bg-[#1B2A4A]/10 flex items-center justify-center text-[#1B2A4A]">
                <UserPlus size={18} />
              </div>
              <div>
                <div className="font-semibold text-[#2B2A26]">Student Lead</div>
                <div className="text-[12px] text-[#8A8371]">Naya student lead add karein</div>
              </div>
            </button>
            <button
              onClick={() => setStep("teacher")}
              className="w-full flex items-center gap-3 p-4 rounded-[3px] bg-white border border-[#D9D2C1] hover:border-[#1B2A4A] transition-colors text-left"
            >
              <div className="w-10 h-10 rounded-full bg-[#C98A2E]/10 flex items-center justify-center text-[#C98A2E]">
                <GraduationCap size={18} />
              </div>
              <div>
                <div className="font-semibold text-[#2B2A26]">Teacher Lead</div>
                <div className="text-[12px] text-[#8A8371]">Naya teacher lead add karein</div>
              </div>
            </button>
          </div>
        )}

        {step === "student" && (
          <VolunteerStudentForm
            createdByTag={createdByTag}
            leads={leads}
            setLeads={setLeads}
            onBack={() => setStep("choose")}
            onDone={() => setStep("done")}
          />
        )}

        {step === "teacher" && (
          <VolunteerTeacherForm
            createdByTag={createdByTag}
            teacherLeads={teacherLeads}
            setTeacherLeads={setTeacherLeads}
            onBack={() => setStep("choose")}
            onDone={() => setStep("done")}
          />
        )}

        {step === "done" && (
          <Paper className="p-6 text-center mt-fadein">
            <div className="text-[#1F6F43] text-[15px] font-semibold mb-3">Lead add ho gaya ✓</div>
            <Btn onClick={() => setStep("choose")} className="w-full justify-center">Ek Aur Add Karein</Btn>
          </Paper>
        )}
      </div>
    </div>
  );
}

