// ---------- Counsellor: Reports ----------
function CounsellorReports({ leads, currentUser }) {
  const myLeads = leads.filter((l) => l.createdBy === currentUser.id);
  const counts = useMemo(() => {
    const c = Object.fromEntries(STATUS_STEPS.map((s) => [s, 0]));
    myLeads.forEach((l) => { c[l.status] = (c[l.status] || 0) + 1; });
    return c;
  }, [myLeads]);
  const total = myLeads.length;
  const converted = counts["Admitted"] || 0;
  const rate = total ? Math.round((converted / total) * 100) : 0;

  return (
    <div>
      <div className="grid grid-cols-3 gap-3 mb-5">
        <Paper className="p-4 text-center">
          <div className="text-[26px] font-serif font-bold text-[#1B2A4A]">{total}</div>
          <div className="text-[10px] uppercase tracking-wide text-[#8A8371] font-semibold mt-0.5">Total Leads</div>
        </Paper>
        <Paper className="p-4 text-center">
          <div className="text-[26px] font-serif font-bold text-[#1F6F43]">{converted}</div>
          <div className="text-[10px] uppercase tracking-wide text-[#8A8371] font-semibold mt-0.5">Admitted</div>
        </Paper>
        <Paper className="p-4 text-center">
          <div className="text-[26px] font-serif font-bold text-[#C98A2E]">{rate}%</div>
          <div className="text-[10px] uppercase tracking-wide text-[#8A8371] font-semibold mt-0.5">Conversion</div>
        </Paper>
      </div>

      <div className="grid sm:grid-cols-5 gap-3 mb-5">
        {STATUS_STEPS.map((s) => (
          <Paper key={s} className="p-3.5 text-center transition-transform hover:-translate-y-0.5 border-t-[3px]" >
            <div style={{ borderTop: `3px solid ${STATUS_COLOR[s]}`, margin: "-14px -14px 10px" }} />
            <div className="text-[24px] font-serif font-semibold" style={{ color: STATUS_COLOR[s] }}>{counts[s]}</div>
            <div className="text-[10px] uppercase tracking-wide text-[#8A8371] font-semibold mt-1">{s}</div>
          </Paper>
        ))}
      </div>

      <Paper className="p-0 overflow-hidden">
        <div className="px-5 py-3.5 flex items-center justify-between border-b border-[#E4DDC9]">
          <div className="flex items-center gap-2 text-[#1B2A4A]">
            <BarChart3 size={17} />
            <h2 className="font-serif text-[17px] font-semibold">Pipeline Overview</h2>
          </div>
        </div>
        <div className="p-5">
          {total === 0 ? (
            <div className="text-[13px] text-[#8A8371]">Data nahi hai abhi.</div>
          ) : (
            <div className="space-y-3">
              {STATUS_STEPS.map((s) => (
                <div key={s} className="flex items-center gap-3">
                  <div className="w-[78px] text-[12px] font-semibold text-[#6B6353] shrink-0">{s}</div>
                  <div className="flex-1 h-2.5 bg-[#E4DDC9] rounded-full overflow-hidden">
                    <div
                      className="h-full rounded-full transition-all"
                      style={{ width: `${total ? (counts[s] / total) * 100 : 0}%`, background: STATUS_COLOR[s] }}
                    />
                  </div>
                  <div className="w-7 text-right text-[12px] font-semibold text-[#2B2A26]">{counts[s]}</div>
                </div>
              ))}
            </div>
          )}
        </div>
      </Paper>
    </div>
  );
}

// ---------- Teacher: Batches ----------
function TeacherBatches({ leads, batches, setBatches }) {
  const [areaFilter, setAreaFilter] = useState("");
  const admittedAll = leads.filter((l) => l.status === "Admitted");
  const admitted = areaFilter ? admittedAll.filter((s) => s.area === areaFilter) : admittedAll;
  const usedAreas = [...new Set(admittedAll.map((s) => s.area).filter(Boolean))];
  const [name, setName] = useState("");
  const [selected, setSelected] = useState([]);
  const [err, setErr] = useState("");

  const toggle = (id) => {
    setSelected((sel) => (sel.includes(id) ? sel.filter((x) => x !== id) : [...sel, id]));
  };

  const create = () => {
    if (!name.trim()) { setErr("Batch ka naam dalen."); return; }
    if (selected.length < 10 || selected.length > 12) {
      setErr(`Batch ke liye 10-12 students select karein (abhi ${selected.length}).`);
      return;
    }
    // batch area = most common area among selected students
    const areaCounts = {};
    selected.forEach((id) => {
      const s = leads.find((l) => l.id === id);
      if (s?.area) areaCounts[s.area] = (areaCounts[s.area] || 0) + 1;
    });
    const batchArea = Object.entries(areaCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || areaFilter || "—";
    setBatches([...batches, { id: nextId("b"), name, area: batchArea, studentIds: selected }]);
    setName(""); setSelected([]); setErr("");
  };

  const batchesByArea = useMemo(() => {
    const groups = {};
    batches.forEach((b) => {
      const key = b.area || "—";
      if (!groups[key]) groups[key] = [];
      groups[key].push(b);
    });
    return groups;
  }, [batches]);

  return (
    <div className="grid md:grid-cols-[1fr_360px] gap-5">
      <Paper className="p-5">
        <div className="flex items-center justify-between mb-1">
          <div className="flex items-center gap-2 text-[#1B2A4A]">
            <Users size={17} />
            <h2 className="font-serif text-[18px]">Admitted Students</h2>
          </div>
          <select
            className={inputCls + " w-auto text-[12px] py-1"}
            value={areaFilter}
            onChange={(e) => setAreaFilter(e.target.value)}
          >
            <option value="">Sab Areas</option>
            {usedAreas.map((a) => <option key={a} value={a}>{a}</option>)}
          </select>
        </div>
        <div className="text-[12px] text-[#8A8371] mb-3">Batch banane ke liye 10-12 students select karein.</div>
        {admitted.length === 0 ? (
          <div className="text-[13px] text-[#8A8371]">Is area mein koi admitted student nahi hai.</div>
        ) : (
          <div className="grid sm:grid-cols-2 gap-2">
            {admitted.map((s) => {
              const checked = selected.includes(s.id);
              return (
                <button
                  key={s.id}
                  onClick={() => toggle(s.id)}
                  className={`flex items-center gap-2 px-3 py-2 rounded-[3px] border text-left text-[13px] ${
                    checked ? "border-[#1B2A4A] bg-[#1B2A4A]/5" : "border-[#D9D2C1] bg-white"
                  }`}
                >
                  {checked ? <CheckSquare size={15} className="text-[#1B2A4A]" /> : <Square size={15} className="text-[#B3AB96]" />}
                  <div>
                    <div className="font-semibold text-[#2B2A26]">{s.name}</div>
                    <div className="text-[11px] text-[#8A8371]">Grade {s.grade || "—"} · {s.area || "—"}</div>
                  </div>
                </button>
              );
            })}
          </div>
        )}
      </Paper>

      <Paper className="p-5 h-fit">
        <div className="flex items-center gap-2 mb-4 text-[#1B2A4A]">
          <Plus size={17} />
          <h2 className="font-serif text-[18px]">Naya Batch</h2>
        </div>
        <div>
          <Field label="Batch Naam">
            <input className={inputCls} placeholder="e.g. Batch A - Morning" value={name} onChange={(e) => setName(e.target.value)} />
          </Field>
          <div className="text-[12px] text-[#6B6353] mb-3">Selected: <b>{selected.length}</b> / 12</div>
          {err && <div className="text-[#B54B3D] text-[12px] mb-3 font-medium">{err}</div>}
          <Btn onClick={create} className="w-full justify-center"><Plus size={15}/> Batch Start Karein</Btn>
        </div>

        {batches.length > 0 && (
          <div className="mt-5 pt-4 border-t border-[#E4DDC9]">
            <div className="text-[11px] uppercase tracking-wide text-[#8A8371] font-semibold mb-3">Batches (Location wise)</div>
            <div className="space-y-3">
              {Object.entries(batchesByArea).map(([area, list]) => (
                <div key={area}>
                  <div className="text-[11px] font-bold text-[#C98A2E] mb-1">{area}</div>
                  <div className="space-y-1">
                    {list.map((b) => (
                      <div key={b.id} className="flex items-center justify-between text-[13px] pl-2">
                        <span className="font-semibold text-[#2B2A26]">{b.name}</span>
                        <span className="text-[#8A8371]">{b.studentIds.length} students</span>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </Paper>
    </div>
  );
}

// ---------- Teacher: Attendance ----------
function TeacherAttendance({ leads, batches, attendance, setAttendance }) {
  const [batchId, setBatchId] = useState(batches[0]?.id || "");
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const batch = batches.find((b) => b.id === batchId);
  const studentsById = Object.fromEntries(leads.map((l) => [l.id, l]));

  const key = `${batchId}__${date}`;
  const records = attendance[key] || {};

  const setStatus = (studentId, present) => {
    setAttendance({
      ...attendance,
      [key]: { ...records, [studentId]: present },
    });
  };

  if (batches.length === 0) {
    return <Paper className="p-6 text-[13px] text-[#8A8371]">Pehle ek Batch banayen "Batches" tab mein.</Paper>;
  }

  return (
    <Paper className="p-5">
      <div className="flex flex-wrap items-center gap-3 mb-4">
        <div className="flex items-center gap-2 text-[#1B2A4A] mr-auto">
          <ClipboardList size={17} />
          <h2 className="font-serif text-[18px]">Attendance</h2>
        </div>
        <select className={inputCls + " w-auto"} value={batchId} onChange={(e) => setBatchId(e.target.value)}>
          {batches.map((b) => <option key={b.id} value={b.id}>{b.name}</option>)}
        </select>
        <input type="date" className={inputCls + " w-auto"} value={date} onChange={(e) => setDate(e.target.value)} />
      </div>

      {batch && (
        <div className="divide-y divide-[#E4DDC9]">
          {batch.studentIds.map((sid) => {
            const s = studentsById[sid];
            if (!s) return null;
            const present = records[sid];
            return (
              <div key={sid} className="flex items-center justify-between py-2.5">
                <div>
                  <div className="text-[14px] font-semibold text-[#2B2A26]">{s.name}</div>
                  <div className="text-[12px] text-[#8A8371]">Grade {s.grade || "—"}</div>
                </div>
                <div className="flex gap-2">
                  <button
                    onClick={() => setStatus(sid, true)}
                    className={`px-3 py-1.5 rounded-[3px] text-[12px] font-semibold border ${
                      present === true ? "bg-[#1F6F43] text-white border-[#1F6F43]" : "border-[#D9D2C1] text-[#6B6353]"
                    }`}
                  >Present</button>
                  <button
                    onClick={() => setStatus(sid, false)}
                    className={`px-3 py-1.5 rounded-[3px] text-[12px] font-semibold border ${
                      present === false ? "bg-[#B54B3D] text-white border-[#B54B3D]" : "border-[#D9D2C1] text-[#6B6353]"
                    }`}
                  >Absent</button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </Paper>
  );
}

// ---------- Teacher: Report ----------
function TeacherReport({ leads, batches, attendance }) {
  const studentsById = Object.fromEntries(leads.map((l) => [l.id, l]));

  const summary = useMemo(() => {
    return batches.map((b) => {
      const dayKeys = Object.keys(attendance).filter((k) => k.startsWith(`${b.id}__`));
      const totalDays = dayKeys.length;
      const perStudent = b.studentIds.map((sid) => {
        let present = 0;
        dayKeys.forEach((k) => { if (attendance[k][sid] === true) present++; });
        return { sid, present, pct: totalDays ? Math.round((present / totalDays) * 100) : 0 };
      });
      return { batch: b, totalDays, perStudent };
    });
  }, [batches, attendance]);

  if (batches.length === 0) {
    return <Paper className="p-6 text-[13px] text-[#8A8371]">Pehle ek Batch banayen aur attendance mark karein.</Paper>;
  }

  return (
    <div className="space-y-5">
      {summary.map(({ batch, totalDays, perStudent }) => (
        <Paper key={batch.id} className="p-5">
          <div className="flex items-center justify-between mb-3">
            <h2 className="font-serif text-[18px] text-[#1B2A4A]">{batch.name}</h2>
            <span className="text-[12px] text-[#8A8371]">{totalDays} din record hue</span>
          </div>
          {totalDays === 0 ? (
            <div className="text-[13px] text-[#8A8371]">Abhi attendance mark nahi hui.</div>
          ) : (
            <div className="space-y-2">
              {perStudent.map(({ sid, present, pct }) => {
                const s = studentsById[sid];
                return (
                  <div key={sid} className="flex items-center gap-3">
                    <div className="w-32 text-[13px] font-semibold text-[#2B2A26] truncate">{s?.name || "—"}</div>
                    <div className="flex-1 h-3 bg-[#E4DDC9] rounded-full overflow-hidden">
                      <div
                        className="h-full rounded-full"
                        style={{ width: `${pct}%`, background: pct >= 75 ? "#1F6F43" : pct >= 50 ? "#C98A2E" : "#B54B3D" }}
                      />
                    </div>
                    <div className="w-16 text-right text-[12px] text-[#6B6353]">{present}/{totalDays} ({pct}%)</div>
                  </div>
                );
              })}
            </div>
          )}
        </Paper>
      ))}
    </div>
  );
}

// ---------- Root ----------
// Firebase setup: data is stored in Cloud Firestore so every user (Admin,
// Counsellor, Teacher, Volunteer), on any device/browser, sees the same data.
import { initializeApp } from "firebase/app";
import { getFirestore, doc, getDoc, setDoc } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "AIzaSyAapE2RFQ8x2fASjVaJ0jqDQnrfF9HcWRs",
  authDomain: "my-teachers-ac709.firebaseapp.com",
  projectId: "my-teachers-ac709",
  storageBucket: "my-teachers-ac709.firebasestorage.app",
  messagingSenderId: "457601313083",
  appId: "1:457601313083:web:20021e3af5f26963686f1e",
  measurementId: "G-JLNZKGKRSP",
};

const firebaseApp = initializeApp(firebaseConfig);
const db = getFirestore(firebaseApp);

// safeStorage: talks to Firestore. Falls back to localStorage if Firestore
// is unreachable, so the app never shows a blank page.
const safeStorage = {
  async get(key) {
    try {
      const snap = await getDoc(doc(db, "myTeachersData", key));
      if (snap.exists()) return { value: snap.data().value };
      return null;
    } catch (e) {
      try {
        const raw = localStorage.getItem("mt_" + key);
        if (raw === null) return null;
        return { value: raw };
      } catch (e2) {
        return null;
      }
    }
  },
  async set(key, value) {
    try {
      await setDoc(doc(db, "myTeachersData", key), { value });
    } catch (e) {
      try {
        localStorage.setItem("mt_" + key, value);
      } catch (e2) {}
    }
  },
};

export default function App() {
  const [users, setUsers] = useState(seedUsers);
  const [leads, setLeads] = useState([]);
  const [teacherLeads, setTeacherLeads] = useState([]);
  const [batches, setBatches] = useState([]);
  const [attendance, setAttendance] = useState({});
  const [currentUser, setCurrentUser] = useState(null);
  const [tab, setTab] = useState("");
  const [loaded, setLoaded] = useState(false);

  // Load saved data once on start
  React.useEffect(() => {
    (async () => {
      const keys = [
        ["users", setUsers],
        ["leads", setLeads],
        ["teacherLeads", setTeacherLeads],
        ["batches", setBatches],
        ["attendance", setAttendance],
      ];
      for (const [key, setter] of keys) {
        try {
          const res = await safeStorage.get(key);
          if (res && res.value) setter(JSON.parse(res.value));
        } catch (e) {
          // key not found yet — keep default
        }
      }
      setLoaded(true);
    })();
  }, []);

  // Save data whenever it changes (after initial load)
  React.useEffect(() => {
    if (!loaded) return;
    safeStorage.set("users", JSON.stringify(users)).catch(() => {});
  }, [users, loaded]);
  React.useEffect(() => {
    if (!loaded) return;
    safeStorage.set("leads", JSON.stringify(leads)).catch(() => {});
  }, [leads, loaded]);
  React.useEffect(() => {
    if (!loaded) return;
    safeStorage.set("teacherLeads", JSON.stringify(teacherLeads)).catch(() => {});
  }, [teacherLeads, loaded]);
  React.useEffect(() => {
    if (!loaded) return;
    safeStorage.set("batches", JSON.stringify(batches)).catch(() => {});
  }, [batches, loaded]);
  React.useEffect(() => {
    if (!loaded) return;
    safeStorage.set("attendance", JSON.stringify(attendance)).catch(() => {});
  }, [attendance, loaded]);

  const login = (u) => {
    setCurrentUser(u);
    if (u.role === "admin") setTab("users");
    else if (u.role === "counsellor") setTab("lead");
    else setTab("batches");
  };
  const logout = () => { setCurrentUser(null); setTab(""); };

  if (!currentUser) return <Login users={users} onLogin={login} />;

  if (currentUser.role === "admin") {
    return (
      <Shell
        user={currentUser}
        onLogout={logout}
        tabs={[
          { key: "users", label: "Users", icon: <Users size={15} /> },
          { key: "alldata", label: "Sara Data", icon: <ClipboardList size={15} /> },
        ]}
        active={tab}
        setActive={setTab}
      >
        {tab === "users" && <AdminUsers users={users} setUsers={setUsers} />}
        {tab === "alldata" && (
          <AdminAllData leads={leads} teacherLeads={teacherLeads} batches={batches} attendance={attendance} />
        )}
      </Shell>
    );
  }

  if (currentUser.role === "counsellor") {
    return (
      <Shell
        user={currentUser}
        onLogout={logout}
        tabs={[
          { key: "lead", label: "Naya Lead", icon: <UserPlus size={15} /> },
          { key: "teacherlead", label: "Naya Teacher", icon: <GraduationCap size={15} /> },
          { key: "reports", label: "Reports", icon: <BarChart3 size={15} /> },
        ]}
        active={tab}
        setActive={setTab}
      >
        {tab === "lead" && <AddLead leads={leads} setLeads={setLeads} currentUser={currentUser} />}
        {tab === "teacherlead" && <AddTeacherLead teacherLeads={teacherLeads} setTeacherLeads={setTeacherLeads} currentUser={currentUser} />}
        {tab === "reports" && <CounsellorReports leads={leads} currentUser={currentUser} />}
      </Shell>
    );
  }

  if (currentUser.role === "volunteer") {
    return (
      <VolunteerFlow
        leads={leads}
        setLeads={setLeads}
        teacherLeads={teacherLeads}
        setTeacherLeads={setTeacherLeads}
        onLogout={logout}
      />
    );
  }

  // teacher
  return (
    <Shell
      user={currentUser}
      onLogout={logout}
      tabs={[
        { key: "batches", label: "Batches", icon: <Users size={15} /> },
        { key: "attendance", label: "Attendance", icon: <ClipboardList size={15} /> },
        { key: "report", label: "Report", icon: <BarChart3 size={15} /> },
      ]}
      active={tab}
      setActive={setTab}
    >
      {tab === "batches" && <TeacherBatches leads={leads} batches={batches} setBatches={setBatches} />}
      {tab === "attendance" && (
        <TeacherAttendance leads={leads} batches={batches} attendance={attendance} setAttendance={setAttendance} />
      )}
      {tab === "report" && <TeacherReport leads={leads} batches={batches} attendance={attendance} />}
    </Shell>
  );
}
